Lemma premap_cells_frameD : forall W m m', premap_cells m -> munch W m m' ->
  disjoint_from W 0xaf708 8 -> disjoint_from W 0x147420 8 -> disjoint_from W 0x149538 8 -> disjoint_from W 0x149580 8 ->
